/* cases: arithmetic cases with exact expected results, shared by the engine tests.
 *
 * The cases aim at the places a decimal engine goes wrong: exact ties (half to even), a
 * carry out of the top digit during rounding, alignment of operands far apart (sticky
 * digits), exact cancellation, and long division.
 */
#ifndef TESTS_CASES_H
#define TESTS_CASES_H

/* Generated by:
 *   from decimal import Decimal as D, getcontext, ROUND_HALF_EVEN
 *   c = getcontext(); c.prec = 34; c.rounding = ROUND_HALF_EVEN
 *   print(D(a) <op> D(b)) for each (op, a, b) below
 */
static const struct { char op; const char *a, *b, *want; } CASES[] = {
    {'+', "0.1", "0.2", "0.3"},
    {'+', "1", "5E-34", "1.000000000000000000000000000000000"},
    {'+', "1.000000000000000000000000000000001", "5E-34", "1.000000000000000000000000000000002"},
    {'+', "9999999999999999999999999999999999", "1", "1.000000000000000000000000000000000E+34"},
    {'+', "9999999999999999999999999999999999", "0.5", "1.000000000000000000000000000000000E+34"},
    {'+', "9999999999999999999999999999999999", "0.4", "9999999999999999999999999999999999"},
    {'-', "1", "1E-50", "1.000000000000000000000000000000000"},
    {'+', "1", "5.0000001E-34", "1.000000000000000000000000000000001"},
    {'-', "1", "5.0000001E-34", "0.9999999999999999999999999999999995"},
    {'-', "1", "5E-35", "1.000000000000000000000000000000000"},
    {'+', "-7", "2", "-5"},
    {'+', "7", "-7", "0"},
    {'-', "3", "3", "0"},
    {'-', "2", "7", "-5"},
    {'+', "1E100", "1", "1.000000000000000000000000000000000E+100"},
    {'-', "1E100", "1", "1.000000000000000000000000000000000E+100"},
    {'-', "1.000000000000000000000000000000001", "1", "1E-33"},
    {'*', "1.5", "1.5", "2.25"},
    {'*', "9999999999999999999999999999999999", "9999999999999999999999999999999999", "9.999999999999999999999999999999998E+67"},
    {'*', "-3", "4", "-12"},
    {'*', "0", "-5", "0"},
    {'*', "1.1", "1.1", "1.21"},
    {'/', "1", "3", "0.3333333333333333333333333333333333"},
    {'/', "2", "3", "0.6666666666666666666666666666666667"},
    {'/', "10", "4", "2.5"},
    {'/', "-1", "8", "-0.125"},
    {'/', "1", "7", "0.1428571428571428571428571428571429"},
    {'/', "149.0987", "52.3947", "2.845682864869920049165278167448234"},
    {'/', "9999999999999999999999999999999999", "3", "3333333333333333333333333333333333"},
    {'/', "1", "1", "1"},
    {'/', "0", "5", "0"},
    {'/', "5", "2E-20", "2.5E+20"},
    {'/', "1E-20", "3", "3.333333333333333333333333333333333E-21"},
    /* Quotients whose digits past the 34th read 5 then 0 with a nonzero remainder:
     * only the remainder decides they round up. */
    {'/', "5", "63", "0.07936507936507936507936507936507937"},
    {'/', "5", "91", "0.05494505494505494505494505494505495"},
    {'/', "5", "99", "0.05050505050505050505050505050505051"},
};

#define NCASES (sizeof CASES / sizeof CASES[0])

#endif
